mapper.update:
update purchase_order set purchase_count = purchase_count - #{parm.goodsCount}
where order_id =#{parm.orderId}
  and purchase_count >= #{parm.goodsCount}

mapper.select:
SELECT DATE_FORMAT(po.create_time, '%Y-%m') AS purchase_month, g.goods_id, g.goods_name, SUM(po.purchase_count) AS purchase_count, SUM(po.purchase_price) AS purchase_price FROM goods g INNER JOIN purchase_order po ON g.goods_id = po.goods_id
AND DATE_FORMAT(po.create_time, '%Y-%m') >= #{parm.startTime}
AND DATE_FORMAT(po.create_time, '%Y-%m') <= #{parm.endTime}
GROUP BY purchase_month, g.goods_id, g.goods_name ORDER BY purchase_month DESC
